let all=[],format="All",syncedAt=null;const REFRESH_MS=20*60*1000,fmt=n=>new Intl.NumberFormat("en-IN").format(n??0),iso=s=>{const m=/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(s||"")||[];return [m[1],m[2],m[3]].filter((x,i)=>x||i>0).map((x,i,a)=>String(Number(x||0)).padStart(i&&a.length>1?2:1,"0")).join(":")||"0:00"},date=s=>new Date(s).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}),stamp=s=>new Date(s).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"});
async function load(){try{const r=await fetch(`content.json?t=${Date.now()}`,{cache:"no-store"}),d=await r.json();if(!r.ok||d.error)throw new Error();all=d.videos.map(v=>({...v,format:(/^PT(?:\d+M)?(?:[0-5]?\dS)?$/.test(v.duration||"")&&Number((/PT(?:(\d+)M)?/.exec(v.duration||"")||[])[1]||0)<1)?"Short":"Video"}));syncedAt=d.syncedAt;draw()}catch{document.getElementById("countLabel")&&(document.getElementById("countLabel").textContent="Live data temporarily unavailable · retrying automatically")}}
function draw(){let list=[...all],page=document.body.dataset.page;if(page==="popular")list.sort((a,b)=>(b.viewCount||0)-(a.viewCount||0));else{const q=(document.getElementById("search")?.value||"").toLowerCase();list=list.filter(v=>(format==="All"||v.format===format)&&v.title.toLowerCase().includes(q));document.getElementById("countLabel").textContent=`${list.length} of ${all.length} public uploads · synced ${stamp(syncedAt)}`}const sync=document.getElementById("syncStatus");if(sync)sync.innerHTML=`<i></i> ${page==="popular"?"Ranked":"Synced"} ${stamp(syncedAt)}`;document.getElementById("contentGrid").innerHTML=list.map((v,i)=>`<article class="content-card" data-id="${v.videoId}"><div class="thumb">${page==="popular"?`<span class="rank">#${i+1}</span>`:""}<img src="${v.thumbnail}" alt=""><span class="duration">${iso(v.duration)}</span></div><div class="card-body"><h2>${v.title}</h2><div class="card-meta"><span>${date(v.publishedAt)}</span><span class="format">${v.format}</span></div><div class="card-stats"><div><b>${fmt(v.viewCount)}</b><span>Views</span></div><div><b>${fmt(v.likeCount)}</b><span>Likes</span></div><div><b>${fmt(v.commentCount)}</b><span>Comments</span></div></div></div></article>`).join("");document.querySelectorAll(".content-card").forEach(c=>c.onclick=()=>detail(cc(c.dataset.id)))}
function cc(id){return all.find(v=>v.videoId===id)}function detail(v){if(v)window.openVideoAnalytics(v,"contentDialog","contentDetail")}
document.getElementById("closeDialog").onclick=()=>document.getElementById("contentDialog").close();document.getElementById("search")?.addEventListener("input",draw);document.querySelectorAll(".filter-tabs button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".filter-tabs button").forEach(x=>x.classList.remove("active"));b.classList.add("active");format=b.dataset.format;draw()});const menu=document.getElementById("menuBtn"),side=document.getElementById("sidebar"),scrim=document.getElementById("scrim");menu.onclick=()=>{side.classList.toggle("open");scrim.classList.toggle("open")};scrim.onclick=()=>{side.classList.remove("open");scrim.classList.remove("open")};document.querySelector(".sidebar nav")?.insertAdjacentHTML("beforeend",'<a href="reports.html">▦ <span>Advanced reports</span></a><a href="planner.html">✓ <span>Content planner</span></a>');load();setInterval(load,REFRESH_MS);
